{
  "blocks": [
    {
      "kind": "dialogue",
      "text": "陈叔直起身子，拍了拍手上的泥，指着那生锈的铁夹子说道：“今儿个一早刚布下的，这地方偏僻，平时也就几只野猪敢来。刚才动静大，我寻思着是只成年的，没想到夹到了这还没长开的小崽子。这附近除了野猪，林子里还有几只黄皮子，不过它们胆子小，一般不往这跑。”",
      "speaker": "k1_person_陈叔"
    }
  ],
  "choices": [
    {
      "action": "interact:ask",
      "targetId": "k1_person_陈叔",
      "stake": "low",
      "purpose": "询问陈叔是否需要帮忙处理这只受伤的野猪崽",
      "anchor": 0
    },
    {
      "action": "interact:decline",
      "targetId": "k1_person_陈叔",
      "stake": "low",
      "purpose": "拒绝陈叔的请求，转身离开",
      "anchor": 0
    },
    {
      "action": "interact:leave",
      "targetId": "k1_person_陈叔",
      "stake": "low",
      "purpose": "结束与陈叔的对话",
      "anchor": 0
    }
  ],
