{
  "blocks": [
    {
      "kind": "dialogue",
      "text": "陈叔见你转身要走，急忙伸手想要拉住你的衣袖，声音里带着几分恳求：“云归，你手艺好，就当积个阴德，帮这小畜生放个血吧，它太疼了。”",
      "speaker": "self"
    }
  ],
  "choices": [
    {
      "action": "interact:ask",
      "targetId": "k1_person_陈叔",
      "stake": "low",
      "purpose": "询问陈叔为何如此执着于放血，是否还有其他解决办法",
      "anchor": 0
    },
    {
      "action": "interact:decline",
      "targetId": "k1_person_陈叔",
      "stake": "low",
      "purpose": "婉拒陈叔的请求，转身离开",
      "anchor": 0
    },
    {
